    <div class="flex items-start gap-4">
      <div class="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">Use request status to diagnose issues: Queued means waiting, Sent means wait for action, Delivered means confirmed, Failed means check contact details and connection. Do not assume missing delivery labels mean the customer ignored the message.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Respond Professionally and Fairly</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Review Request Statuses</p>
          <p class="text-slate-600 text-sm">Go to Reputation → Requests and review the status of recent requests.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Diagnose Failed Requests</p>
          <p class="text-slate-600 text-sm">For any failed requests, check the email address, phone number, sender settings, and connection.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Document Common Issues</p>
          <p class="text-slate-600 text-sm">Write down the most common failure reasons and fixes for your business.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Track Requests and Fix Failures',
      lesson_number = 4,
      sort_order = 4,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Track Requests and Fix Failures';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Track Requests and Fix Failures

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'track-requests-fix-failures' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson track-requests-fix-failures not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''Failed'' tell you?', 
    '["The customer ignored the message.","The request could not be delivered.","The request is still queued.","The review was negative."]'::jsonb,
    'The request could not be delivered.',
    '''Failed'' means the message could not be delivered. Check the email address, phone number, sender settings, and connection to fix the issue.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Name two contact details that may cause a request failure.', 
    '["The email address and phone number.","The customer''s name and address.","The business name and location.","The review platform and widget settings."]'::jsonb,
    'The email address and phone number.',
    'Incorrect or missing email addresses and phone numbers are the most common causes of request delivery failures.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you avoid sending another request immediately when the first one shows Sent?', 
    '["The customer may already have received it and needs reasonable time to respond.","LeadProspectrr does not allow multiple requests.","It will cost extra credits.","The first request will be cancelled."]'::jsonb,
    'The customer may already have received it and needs reasonable time to respond.',
    'When a request shows Sent, the customer may already have received it. Give them reasonable time to respond before sending a follow-up.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
